SELECT "On_Time_On_Time_Performance_2016_1"."WeatherDelay", "L_DIVERSIONS"."Code", MAX("On_Time_On_Time_Performance_2016_1"."ArrTime"), SUM("On_Time_On_Time_Performance_2016_1"."ActualElapsedTime"), MAX("L_DIVERSIONS"."Code")
