SELECT "On_Time_On_Time_Performance_2016_1"."Year", "L_ONTIME_DELAY_GROUPS"."Description", "On_Time_On_Time_Performance_2016_1"."OriginCityMarketID", "L_ONTIME_DELAY_GROUPS"."Code", "L_ONTIME_DELAY_GROUPS"."Code", MIN("L_ONTIME_DELAY_GROUPS"."Code")
FROM "L_ONTIME_DELAY_GROUPS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_ONTIME_DELAY_GROUPS"."Code" = "On_Time_On_Time_Performance_2016_1"."ArrivalDelayGroups" WHERE "On_Time_On_Time_Performance_2016_1"."NASDelay" != 133.7247052490402 OR "On_Time_On_Time_Performance_2016_1"."DestAirportSeqID" != 1307300 OR "L_ONTIME_DELAY_GROUPS"."Code" < -1 OR "On_Time_On_Time_Performance_2016_1"."Month" < 103 OR "L_ONTIME_DELAY_GROUPS"."Code" != 1 GROUP BY "On_Time_On_Time_Performance_2016_1"."Year", "L_ONTIME_DELAY_GROUPS"."Description", "On_Time_On_Time_Performance_2016_1"."OriginCityMarketID", "L_ONTIME_DELAY_GROUPS"."Code", "L_ONTIME_DELAY_GROUPS"."Code" ORDER BY "L_ONTIME_DELAY_GROUPS"."Code" ASC, "L_ONTIME_DELAY_GROUPS"."Code" ASC LIMIT 397;

SELECT "L_ONTIME_DELAY_GROUPS"."Code", "L_ONTIME_DELAY_GROUPS"."Code", AVG("L_ONTIME_DELAY_GROUPS"."Code"), SUM("L_ONTIME_DELAY_GROUPS"."Code"), MIN("L_WORLD_AREA_CODES"."Code")
FROM "L_WORLD_AREA_CODES" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_WORLD_AREA_CODES"."Code" = "On_Time_On_Time_Performance_2016_1"."DestWac" LEFT JOIN "L_ONTIME_DELAY_GROUPS" ON "On_Time_On_Time_Performance_2016_1"."ArrivalDelayGroups" = "L_ONTIME_DELAY_GROUPS"."Code" WHERE "L_WORLD_AREA_CODES"."Code" = 772 OR "L_WORLD_AREA_CODES"."Code" < 440 OR "L_ONTIME_DELAY_GROUPS"."Code" > 8 GROUP BY "L_ONTIME_DELAY_GROUPS"."Code", "L_ONTIME_DELAY_GROUPS"."Code" LIMIT 129;

SELECT "L_STATE_ABR_AVIATION"."Code", "L_WEEKDAYS"."Code", "On_Time_On_Time_Performance_2016_1"."OriginWac", "On_Time_On_Time_Performance_2016_1"."DestAirportID", "L_WORLD_AREA_CODES"."Code", MAX("L_WORLD_AREA_CODES"."Code")
FROM "L_WEEKDAYS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_WEEKDAYS"."Code" = "On_Time_On_Time_Performance_2016_1"."DayOfWeek" LEFT JOIN "L_STATE_ABR_AVIATION" ON "On_Time_On_Time_Performance_2016_1"."DestState" = "L_STATE_ABR_AVIATION"."Code" JOIN "L_WORLD_AREA_CODES" ON "On_Time_On_Time_Performance_2016_1"."OriginWac" = "L_WORLD_AREA_CODES"."Code" WHERE "L_WEEKDAYS"."Code" <= 2 GROUP BY "L_STATE_ABR_AVIATION"."Code", "L_WEEKDAYS"."Code", "On_Time_On_Time_Performance_2016_1"."OriginWac", "On_Time_On_Time_Performance_2016_1"."DestAirportID", "L_WORLD_AREA_CODES"."Code" ORDER BY "L_WEEKDAYS"."Code" DESC, "On_Time_On_Time_Performance_2016_1"."DestAirportID" DESC;

SELECT "L_WORLD_AREA_CODES"."Code", "L_WEEKDAYS"."Code", "L_WEEKDAYS"."Code", "L_WORLD_AREA_CODES"."Description", MIN("L_WEEKDAYS"."Code"), AVG("L_WORLD_AREA_CODES"."Code")
FROM "L_WORLD_AREA_CODES" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_WORLD_AREA_CODES"."Code" = "On_Time_On_Time_Performance_2016_1"."DestWac" JOIN "L_WEEKDAYS" ON "On_Time_On_Time_Performance_2016_1"."DayOfWeek" = "L_WEEKDAYS"."Code" WHERE "L_WORLD_AREA_CODES"."Code" <= 967 OR "L_WEEKDAYS"."Code" <= 8 OR "L_WORLD_AREA_CODES"."Description" != 'Saint Helena, Ascension, and Tristan da Cunha' OR "L_WEEKDAYS"."Code" != 4 OR "L_WORLD_AREA_CODES"."Description" = 'Lesotho' GROUP BY "L_WORLD_AREA_CODES"."Code", "L_WEEKDAYS"."Code", "L_WEEKDAYS"."Code", "L_WORLD_AREA_CODES"."Description" HAVING MIN("L_WEEKDAYS"."Code") > 93 ORDER BY AVG("L_WORLD_AREA_CODES"."Code") DESC, "L_WEEKDAYS"."Code" ASC;

SELECT "L_AIRPORT_ID"."Code", "L_AIRLINE_ID"."Code", "On_Time_On_Time_Performance_2016_1"."DayofMonth", "L_AIRPORT_ID"."Code", "L_AIRPORT_SEQ_ID"."Description", AVG("L_AIRPORT_ID"."Code"), COUNT("On_Time_On_Time_Performance_2016_1"."TaxiIn"), SUM("L_AIRLINE_ID"."Code")
FROM "L_AIRLINE_ID" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_AIRLINE_ID"."Code" = "On_Time_On_Time_Performance_2016_1"."AirlineID" LEFT JOIN "L_AIRPORT_SEQ_ID" ON "On_Time_On_Time_Performance_2016_1"."OriginAirportSeqID" = "L_AIRPORT_SEQ_ID"."Code" JOIN "L_AIRPORT_ID" ON "On_Time_On_Time_Performance_2016_1"."Div2AirportID" = "L_AIRPORT_ID"."Code" WHERE "L_AIRLINE_ID"."Code" > 19348 AND "L_AIRPORT_ID"."Description" != 'Puerto Maldonado, Peru: Padre Aldamiz' AND "L_AIRPORT_ID"."Code" != 10354 AND "On_Time_On_Time_Performance_2016_1"."OriginStateName" = 'Nevada' AND "L_AIRPORT_ID"."Description" LIKE '%Norman, OK: University of Oklahoma/Max Westheimer%' GROUP BY "L_AIRPORT_ID"."Code", "L_AIRLINE_ID"."Code", "On_Time_On_Time_Performance_2016_1"."DayofMonth", "L_AIRPORT_ID"."Code", "L_AIRPORT_SEQ_ID"."Description" HAVING AVG("L_AIRPORT_ID"."Code") > 67;

SELECT "L_STATE_ABR_AVIATION"."Code", "L_STATE_ABR_AVIATION"."Description", "L_STATE_ABR_AVIATION"."Code"
FROM "L_STATE_ABR_AVIATION" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_STATE_ABR_AVIATION"."Code" = "On_Time_On_Time_Performance_2016_1"."DestState" JOIN "L_STATE_FIPS" ON "On_Time_On_Time_Performance_2016_1"."OriginStateFips" = "L_STATE_FIPS"."Code" WHERE "L_STATE_ABR_AVIATION"."Description" = 'Massachusetts' AND "L_STATE_FIPS"."Code" != 1 AND "L_STATE_ABR_AVIATION"."Description" != 'Nevada' AND "L_STATE_FIPS"."Description" = 'Palau (Fips Pub 55-3)' ORDER BY "L_STATE_ABR_AVIATION"."Code" DESC, "L_STATE_ABR_AVIATION"."Description" DESC;

SELECT "L_CITY_MARKET_ID"."Code", "On_Time_On_Time_Performance_2016_1"."OriginStateName", "L_CITY_MARKET_ID"."Code", "L_CITY_MARKET_ID"."Description", "L_CITY_MARKET_ID"."Code", MAX("L_CITY_MARKET_ID"."Code"), SUM("L_CITY_MARKET_ID"."Code")
FROM "L_CITY_MARKET_ID" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_CITY_MARKET_ID"."Code" = "On_Time_On_Time_Performance_2016_1"."OriginCityMarketID" WHERE "On_Time_On_Time_Performance_2016_1"."ArrDelay" != -4.140003559800796 AND "L_CITY_MARKET_ID"."Code" >= 73428 GROUP BY "L_CITY_MARKET_ID"."Code", "On_Time_On_Time_Performance_2016_1"."OriginStateName", "L_CITY_MARKET_ID"."Code", "L_CITY_MARKET_ID"."Description", "L_CITY_MARKET_ID"."Code" ORDER BY "L_CITY_MARKET_ID"."Code" ASC, "L_CITY_MARKET_ID"."Description" ASC;

